def parse_records(text):
    lines = text.splitlines()
    out = []
    for l in lines:
        # A line that is entirely a comment (only a comment) is dropped.
        if l.strip().startswith('#'):
            continue
        # Strip inline comment content (everything from the first '#').
        if '#' in l:
            l = l.split('#', 1)[0]
        out.append(l.strip())
    return out

